events.command:
/usr/bin/bash -lc 'set -o pipefail
check_subset() {
  local input="$1" output="$2" label="$3"
  awk '"'
    NR==FNR {
      phase=(FNR-1)%4
      if (phase==0) { id="'$0; sub(/''^@/,"",id); sub(/[[:space:]].*/,"",id); seen[id]=1 }
      else if (phase==1) seq[id]=$0
      else if (phase==2) plus[id]=$0
      else qual[id]=$0
      next
    }
    {
      phase=(FNR-1)%4
      if (phase==0) { id=$0; sub(/''^@/,"",id); sub(/[[:space:]].*/,"",id); n++; if (!(id in seen)) bad++ }
      else if (phase==1 && seq[id] != $0) bad++
      else if (phase==2 && plus[id] != $0) bad++
      else if (phase==3 && qual[id] != $0) bad++
    }
    END { printf "%s'"\\tretained_records=%d\\tcontent_mismatches=%d\\n\", label, n, bad; exit (bad "'!= 0) }
  '"' <(gzip -cd \""'$input") <(gzip -cd "$output")
}
check_subset data/inputs/short_reads/pair/forward/forward.fastqsanger.gz final_answer/filtered_forward.fastqsanger.gz forward
check_subset data/inputs/short_reads/pair/reverse/reverse.fastqsanger.gz final_answer/filtered_reverse.fastqsanger.gz reverse'
